// Builds one LLM request per successfully scraped page.
// Index mapping to "URLs" is safe: Fetch/Extract nodes output exactly one item per input item.
const urls = $('URLs').all();
const model = $('Config').first().json.llm_model;

const system = [
  'You extract product data from the raw text of a web page.',
  'Return only a single JSON object. No markdown, no explanations.',
  'Keys (all required): title (string), price (number), currency (string), in_stock (boolean), promo (string or null), rating (number or null), reviews_count (integer or null).',
  'Rules:',
  '- price: number without currency symbol, decimal point.',
  '- currency: ISO code (EUR, USD, GBP), inferred from the symbol.',
  '- in_stock: true if the text says the item is available, otherwise false.',
  '- rating: number from 1 to 5. Map a CSS class such as "star-rating Three" to 3.',
  '- reviews_count: integer if present, otherwise null.',
  '- promo: text of any discount or promotion, otherwise null.',
  '- If a field is not present in the text, return null. Do not invent values.'
].join('\n');

const out = [];
$input.all().forEach((it, i) => {
  const j = it.json;
  if (j.error || !j.raw_text) return; // scrape failed: counted later as "failed"
  const parts = [j.raw_text];
  if (j.info_table) parts.push('Product information: ' + j.info_table);
  if (j.rating_class) parts.push('Rating CSS class: ' + j.rating_class);
  const text = parts.join('\n').slice(0, 6000);
  out.push({
    json: {
      url: urls[i].json.url,
      body: {
        model,
        temperature: 0,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: 'Page text:\n' + text }
        ],
        response_format: { type: 'json_object' }
      }
    }
  });
});

if (out.length === 0) {
  throw new Error('All page fetches failed: nothing to process');
}
return out;

// Parses the LLM answer and validates it. Invalid items are flagged, not dropped silently.
const built = $('Build LLM request').all();
const out = [];

$input.all().forEach((it, i) => {
  const url = built[i].json.url;
  const errors = [];
  let item = {};

  try {
    const raw = it.json.choices[0].message.content;
    // some models wrap JSON in a markdown fence: strip it before parsing
    item = JSON.parse(raw.replace(/```json|```/g, '').trim());
    // free models sometimes return numbers/booleans as strings: coerce
    if (typeof item.price === 'string') item.price = parseFloat(item.price.replace(',', '.'));
    if (typeof item.in_stock === 'string') item.in_stock = item.in_stock.toLowerCase() === 'true';
    if (typeof item.rating === 'string') item.rating = parseFloat(item.rating) || null;
    if (typeof item.currency === 'string') item.currency = item.currency.trim().toUpperCase();
  } catch (e) {
    errors.push('llm_response');
  }

  if (typeof item.title !== 'string' || !item.title) errors.push('title');
  if (typeof item.price !== 'number' || !(item.price > 0)) errors.push('price');
  if (typeof item.in_stock !== 'boolean') errors.push('in_stock');
  if (typeof item.currency !== 'string' || item.currency.length !== 3) errors.push('currency');

  const usage = it.json.usage || {};
  out.push({
    json: {
      url,
      ...item,
      scraped_at: new Date().toISOString(),
      valid: errors.length === 0,
      errors,
      prompt_tokens: usage.prompt_tokens || 0,
      completion_tokens: usage.completion_tokens || 0
    }
  });
});

return out;

// Compares fresh snapshots with the last stored snapshot per URL.
const current = $('Validate').all().map(i => i.json);
const valid = current.filter(i => i.valid);
const totalUrls = $('URLs').all().length;

if (valid.length === 0) {
  throw new Error('No valid products extracted: check scraping selectors and LLM step');
}

// Google Sheets returns everything as strings, so cast explicitly.
const history = $('Read snapshots').all()
  .map(i => i.json)
  .filter(r => r.url)
  .sort((a, b) => String(a.scraped_at).localeCompare(String(b.scraped_at)));

const last = {};
for (const r of history) last[r.url] = r; // chronological: latest row wins

const toBool = v => String(v).toLowerCase() === 'true';
const today = new Date().toISOString().slice(0, 10);

const changes = [];
const rows = [];

for (const c of valid) {
  const p = last[c.url];
  let skip = false;

  if (p) {
    const oldPrice = Number(p.price);
    const oldStock = toBool(p.in_stock);
    const oldPromo = p.promo || null;
    const oldRating = p.rating === '' || p.rating == null ? null : Number(p.rating);
    const newPromo = c.promo || null;

    if (c.price !== oldPrice) {
      changes.push({ type: 'price', title: c.title, url: c.url, from: oldPrice, to: c.price, currency: c.currency });
    }
    if (c.in_stock !== oldStock) {
      changes.push({ type: 'stock', title: c.title, url: c.url, from: oldStock, to: c.in_stock });
    }
    if (newPromo !== oldPromo) {
      changes.push({ type: 'promo', title: c.title, url: c.url, from: oldPromo, to: newPromo });
    }
    if (oldRating !== null && c.rating != null && oldRating - c.rating >= 0.3) {
      changes.push({ type: 'rating', title: c.title, url: c.url, from: oldRating, to: c.rating });
    }

    // Deduplication: same day + nothing changed => do not write another row.
    const sameDay = String(p.scraped_at).slice(0, 10) === today;
    const unchanged = c.price === oldPrice && c.in_stock === oldStock && newPromo === oldPromo;
    skip = sameDay && unchanged;
  }

  rows.push({
    skip,
    row: {
      scraped_at: c.scraped_at,
      url: c.url,
      title: c.title,
      price: c.price,
      currency: c.currency,
      in_stock: String(c.in_stock),
      promo: c.promo || '',
      rating: c.rating == null ? '' : c.rating,
      reviews_count: c.reviews_count == null ? '' : c.reviews_count
    }
  });
}

return [{
  json: {
    changes,
    rows,
    isFirstRun: Object.keys(last).length === 0,
    total_urls: totalUrls,
    valid_count: valid.length,
    failed_count: totalUrls - valid.length,
    prompt_tokens: current.reduce((s, i) => s + (i.prompt_tokens || 0), 0),
    completion_tokens: current.reduce((s, i) => s + (i.completion_tokens || 0), 0)
  }
}];

// Formats the Telegram digest (HTML parse mode).
const d = $json;
const cfg = $('Config').first().json;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const date = new Date().toISOString().slice(0, 10);
const by = t => d.changes.filter(c => c.type === t);

const lines = [
  '📊 <b>Competitor monitoring, ' + date + '</b>',
  'Checked: ' + d.valid_count + ' of ' + d.total_urls + ', changes: ' + d.changes.length
];

if (d.isFirstRun) {
  lines.push('ℹ️ First run: baseline saved, nothing to compare yet.');
}

const prices = by('price');
if (prices.length) {
  lines.push('', '💰 <b>Price</b>');
  for (const c of prices) {
    const pct = c.from ? ((c.to - c.from) / c.from * 100).toFixed(1) : '0.0';
    const sign = c.to > c.from ? '+' : '';
    lines.push('• ' + esc(c.title) + ': ' + c.from + ' → ' + c.to + ' ' + esc(c.currency) + ' (' + sign + pct + '%)');
    lines.push('  ' + esc(c.url));
  }
}

const stock = by('stock');
if (stock.length) {
  lines.push('', '📦 <b>Availability</b>');
  for (const c of stock) {
    lines.push('• ' + esc(c.title) + ': ' + (c.to ? 'back in stock' : 'out of stock'));
    lines.push('  ' + esc(c.url));
  }
}

const promo = by('promo');
if (promo.length) {
  lines.push('', '🏷 <b>Promo</b>');
  for (const c of promo) {
    lines.push('• ' + esc(c.title) + ': ' + esc(c.from || 'none') + ' → ' + esc(c.to || 'none'));
    lines.push('  ' + esc(c.url));
  }
}

const rating = by('rating');
if (rating.length) {
  lines.push('', '⭐ <b>Rating drop</b>');
  for (const c of rating) {
    lines.push('• ' + esc(c.title) + ': ' + c.from + ' → ' + c.to);
    lines.push('  ' + esc(c.url));
  }
}

if (d.failed_count > 0) {
  lines.push('', '⚠️ Could not process: ' + d.failed_count);
}

lines.push('', '🧮 LLM tokens: ' + d.prompt_tokens + ' in / ' + d.completion_tokens + ' out');

const shouldSend = d.changes.length > 0 || d.failed_count > 0 || cfg.send_if_no_changes === true;
return [{ json: { text: lines.join('\n'), chat_id: cfg.telegram_chat_id, should_send: shouldSend } }];
